html,body { background:var(--appsmith-theme-surfaceColor, #0f172a) !important; margin:0; padding:0; }
.app { width:100%; box-sizing:border-box; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; }
.ag-theme-alpine { --ag-header-background-color:var(--appsmith-theme-surfaceColor, #0f172a); --ag-header-foreground-color:var(--appsmith-theme-textStrongColor, #ffffff); --ag-odd-row-background-color:var(--appsmith-theme-surfaceColor, #0f172a); --ag-background-color:var(--appsmith-theme-surfaceColor, #0f172a); --ag-row-hover-color:var(--appsmith-theme-surfaceHoverColor, #26344b); --ag-selected-row-background-color:var(--appsmith-theme-surfaceHoverColor, #26344b); --ag-foreground-color:var(--appsmith-theme-textColor, #e2e8f0); --ag-border-color:var(--appsmith-theme-borderColor, #334155); --ag-font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; --ag-font-size:14px; --ag-row-height:44px; --ag-header-height:48px; border-radius:6px; border:1px solid var(--appsmith-theme-borderColor, #334155); overflow:hidden; }
.ag-theme-alpine .ag-row-odd { background-color:var(--appsmith-theme-surfaceColor, #0f172a) !important; }
.ag-theme-alpine .ag-row-even { background-color:var(--appsmith-theme-surfaceAltColor, #1e293b) !important; }
.ag-theme-alpine .ag-row-hover { background-color:var(--appsmith-theme-surfaceHoverColor, #26344b) !important; }
.ag-theme-alpine .ag-cell { border-right:1px solid color-mix(in srgb, var(--appsmith-theme-textStrongColor, #ffffff) 4%, transparent); line-height:44px; }
.ag-theme-alpine .ag-header { font-weight:600; background:var(--appsmith-theme-surfaceColor, #0f172a); border-bottom:2px solid var(--appsmith-theme-borderColor, #334155); }
.ag-theme-alpine .ag-header-cell-text { color:var(--appsmith-theme-textStrongColor, #ffffff); }
.ag-theme-alpine .ag-paging-panel { background:var(--appsmith-theme-surfaceColor, #0f172a); color:var(--appsmith-theme-textStrongColor, #ffffff); border-top:2px solid var(--appsmith-theme-borderColor, #334155); }
.ag-theme-alpine .ag-paging-panel * { color:var(--appsmith-theme-textStrongColor, #ffffff) !important; }
.detail-link { color:var(--appsmith-theme-linkColor, #60a5fa); cursor:pointer; font-weight:600; }
.ag-cell:hover .detail-link { text-decoration:underline; }
.pill { display:inline-flex; align-items:center; gap:7px; }
.dot { width:8px; height:8px; border-radius:50%; display:inline-block; }
::-webkit-scrollbar { width:10px; height:10px; background:var(--appsmith-theme-surfaceColor, #0f172a); }
::-webkit-scrollbar-thumb { background:var(--appsmith-theme-backgroundColor, #1E293A); border-radius:4px; border:2px solid var(--appsmith-theme-surfaceColor, #0f172a); }
* { scrollbar-color:var(--appsmith-theme-surfaceAltColor, #1e293b) var(--appsmith-theme-surfaceColor, #0f172a); scrollbar-width:thin; }

