function statusRenderer(p){
  var v = p.value; var open = String(v).toLowerCase() === 'open';
  var color = open ? 'var(--appsmith-theme-successColor, #34d399)' : (String(v).toLowerCase() === 'closed' ? 'var(--appsmith-theme-dangerColor, #f87171)' : 'var(--appsmith-theme-textSecondaryColor, #94a3b8)');
  return '<span class="pill"><span class="dot" style="background:'+color+'"></span>'+(v==null?'':v)+'</span>';
}
var COLS = [
  { headerName:'Vendor', field:'Vendor', flex:1, minWidth:120 },
  { headerName:'Billing ID', field:'Billing ID', flex:1, minWidth:120 },
  { headerName:'Service Account', field:'Service Account', flex:1, minWidth:130 },
  { headerName:'Meter ID', field:'Meter ID', flex:1, minWidth:110 },
  { headerName:'Utility', field:'Utility', width:110 },
  { headerName:'Type', field:'Type', width:150 },
  { headerName:'Last Bill', field:'Last Bill', width:120 },
  { headerName:'Open/Closed', field:'Open/Closed', width:130, cellRenderer:statusRenderer },
  { headerName:'', colId:'billhistory', field:'id', width:120, sortable:false, resizable:false, cellRenderer:function(){ return '<span class="detail-link">Bill History</span>'; } },
  { headerName:'', colId:'actions', field:'id', width:100, sortable:false, resizable:false, cellRenderer:function(){ return '<span class="detail-link">Details</span>'; } }
];
var gridApi = null, lastSig = '';
function getRows(m){ return (m && Array.isArray(m.data)) ? m.data : []; }
function sig(m){ var r=getRows(m); return (m&&m.isLoading?'L':'')+r.length+':'+(r[0]&&r[0].id)+':'+(r[r.length-1]&&r[r.length-1].id); }
function onCellClicked(e){
  if (!e.column) return;
  var col = e.column.getColId();
  if (col === 'actions') { appsmith.updateModel({ vaSelected: e.data }); appsmith.triggerEvent('onDetails'); }
  else if (col === 'billhistory') { appsmith.updateModel({ vaSelected: e.data }); appsmith.triggerEvent('onBillHistory'); }
}
function render(m){
  var el = document.querySelector('#myGrid'); if(!el) return; el.innerHTML='';
  gridApi = agGrid.createGrid(el, {
    columnDefs: COLS, rowData: getRows(m),
    defaultColDef: { resizable:true, sortable:true, minWidth:90 },
    animateRows:true, popupParent:document.body,
    getRowId:function(p){ return String(p.data.id); },
    overlayNoRowsTemplate:'<span style="color:var(--appsmith-theme-textSecondaryColor, #94a3b8);font-style:italic;">No virtual accounts</span>',
    onGridReady:function(p){ gridApi=p.api; }, onCellClicked:onCellClicked
  });
  lastSig = sig(m);
}
appsmith.onReady(function(){
  render(appsmith.model);
  appsmith.onModelChange(function(m){
    if(!gridApi){ render(m); return; }
    var s=sig(m); if(s!==lastSig){ lastSig=s; gridApi.setGridOption('rowData', getRows(m)); }
  });
});

